import{_ as s,o as a,c as i,an as o}from"./chunks/framework.CbxhlEWH.js";const k=JSON.parse('{"title":"xlogy/xlog1py Mooncake rules","description":"","frontmatter":{},"headers":[],"relativePath":"tools/xlogy.md","filePath":"tools/xlogy.md","lastUpdated":null}'),t={name:"tools/xlogy.md"};function n(r,e,h,l,d,p){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="xlogy" tabindex="-1"><code>xlogy</code>/<code>xlog1py</code> Mooncake rules <a class="header-anchor" href="#xlogy" aria-label="Permalink to &quot;`xlogy`/`xlog1py` Mooncake rules {#xlogy}&quot;">​</a></h1><h2 id="The-problem" tabindex="-1">The problem <a class="header-anchor" href="#The-problem" aria-label="Permalink to &quot;The problem {#The-problem}&quot;">​</a></h2><p>Mooncake has no rule for <code>LogExpFunctions.xlogy</code> or <code>xlog1py</code>, so it derives one by differentiating the primal</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xlogy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x, y) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> iszero</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;&amp;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> !</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">isnan</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(y) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> zero</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(y)) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> x </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> log</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(y)</span></span></code></pre></div><p>The <code>iszero(x)</code> branch returns a constant, so the derived rule reports <code>∂/∂x = 0</code> at <code>x == 0</code> where the correct value is <code>log(y)</code>.</p><p><code>Distributions.gammalogpdf</code> computes <code>xlogy(shape - 1, x / scale)</code>, so the first argument is exactly zero whenever a Gamma log-density is differentiated at <code>shape == 1</code>. The shape component of the gradient then comes back as <code>-digamma(1) ≈ 0.5772</code> instead of <code>log(x / scale) - digamma(1)</code>, in both Mooncake modes. Nothing errors; the number is simply wrong, and only at that one point.</p><p>A shared-hyperparameter model reaches this more often than the exponent suggests: a population-level draw can land a stratum&#39;s reconstructed shape on exactly <code>1.0</code>, which is what <a href="https://github.com/EpiAware/ComposedDistributions.jl/issues/99" target="_blank" rel="noreferrer">ComposedDistributions#99</a> first hit.</p><h2 id="The-fix" tabindex="-1">The fix <a class="header-anchor" href="#The-fix" aria-label="Permalink to &quot;The fix {#The-fix}&quot;">​</a></h2><p><code>EpiAwareADToolsLogExpFunctionsMooncakeExt</code> registers both functions as Mooncake primitives on <code>Base.IEEEFloat</code> arguments and lifts the rules <code>LogExpFunctionsChainRulesCoreExt</code> already ships:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Mooncake</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">@from_chainrules</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Mooncake</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DefaultCtx Tuple{</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    typeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(xlogy), Base</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">IEEEFloat, Base</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">IEEEFloat}</span></span></code></pre></div><p><code>@from_chainrules</code> rather than <code>@from_rrule</code> is deliberate. LogExpFunctions supplies an <code>frule</code> as well as an <code>rrule</code>, and <code>@from_rrule</code> lifts only the reverse direction, leaving Mooncake forward mode deriving the same wrong zero (<a href="https://github.com/EpiAware/ComposedDistributions.jl/issues/214" target="_blank" rel="noreferrer">ComposedDistributions#214</a>).</p><p>This is narrowly-scoped type piracy on functions this package does not own. It is hosted here so that consumers share one copy: two packages each defining it is a duplicate method registration, which Julia 1.12 rejects as method overwriting during precompilation (<a href="https://github.com/EpiAware/DistributionsInference.jl/issues/73" target="_blank" rel="noreferrer">DistributionsInference#73</a>).</p><h2 id="What-a-consumer-has-to-do" tabindex="-1">What a consumer has to do <a class="header-anchor" href="#What-a-consumer-has-to-do" aria-label="Permalink to &quot;What a consumer has to do {#What-a-consumer-has-to-do}&quot;">​</a></h2><p>The extension&#39;s triggers are <code>ChainRulesCore</code>, <code>LogExpFunctions</code> and <code>Mooncake</code>, so all three must be <em>loaded modules</em> in the session, not merely listed in a <code>[deps]</code> section.</p><ul><li><p><code>Mooncake</code> is loaded by whoever chose the backend, and it brings <code>ChainRulesCore</code> with it.</p></li><li><p><code>LogExpFunctions</code> is usually already there through <code>Distributions</code> → <code>StatsFuns</code> → <code>LogExpFunctions</code>, but relying on that is relying on someone else&#39;s dependency graph. A package that needs the rules should load it itself, for effect if not for names, alongside <code>EpiAwareADTools</code>.</p></li></ul><p><code>ComposedDistributions</code> and <code>DistributionsInference</code> both do this, and both keep a <code>shape == 1</code> gradient scenario in their AD matrices as the regression test that the rules still reach them.</p><h2 id="Upstream-target" tabindex="-1">Upstream target <a class="header-anchor" href="#Upstream-target" aria-label="Permalink to &quot;Upstream target {#Upstream-target}&quot;">​</a></h2><p>A rule for <code>xlogy</code>/<code>xlog1py</code> in <code>Mooncake.jl</code> itself. The report (<a href="https://github.com/chalk-lab/Mooncake.jl/issues/1241" target="_blank" rel="noreferrer">issue #1241</a>) was withdrawn as bot-filed rather than fixed, so the gap is still open in Mooncake 0.5.45 and the report awaits a re-file. This extension is deleted once Mooncake registers its own primitives.</p>',18)])])}const g=s(t,[["render",n]]);export{k as __pageData,g as default};
